    "loginStatus" TEXT,
    photo TEXT,
    signature TEXT,
    organization TEXT,
    organization_id TEXT,
    "pluginRevision" BIGINT NOT NULL DEFAULT 0,
    "pluginArchivedAt" TIMESTAMPTZ,
    "pluginArchiveReason" TEXT
);
